steps.action:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'product' in ch['name'].lower() or 'launch' in ch['name'].lower():
            print(f\"{ch['id']} - {ch['name']}\")
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&channel=C_LAUNCH&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        text = msg.get('text', '')
        print(f\"ts={msg['ts']} | user={msg.get('user','?')} | text={text[:200]}\")
        if 'reactions' in msg:
            for r in msg['reactions']:
                print(f\"  reaction: {r['name']} by {r['users']}\")
        print()
else:
    print(json.dumps(data, indent=2))
"

